import { View, Text, Pressable, StyleSheet } from "react-native";
import { createContext, useContext, useState } from "react";
import { registerRootComponent } from "expo";

const CartContext = createContext({ count: 0, add: () => {} });

function Badge() {
  const { count } = useContext(CartContext);
  return <Text nativeID="badge" style={styles.badge}>Сагс: {count}</Text>;
}
function AddButton() {
  const { add } = useContext(CartContext);
  return <Pressable nativeID="add" style={styles.b} onPress={add}><Text style={styles.t}>Сагслах</Text></Pressable>;
}

function App() {
  const [count, setCount] = useState(0);
  const add = () => setCount((c) => c + 1);
  return (
    // энд бичнэ үү: Provider value={{ count, add }}
    <View style={styles.s}>
      <Badge />
      <AddButton />
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, gap: 16, alignItems: "center", justifyContent: "center" },
  badge: { fontSize: 22, fontWeight: "bold" },
  b: { backgroundColor: "#2563eb", padding: 14, borderRadius: 12 }, t: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);

import { View, Text, Pressable, StyleSheet } from "react-native";
import { createContext, useContext, useState } from "react";
import { registerRootComponent } from "expo";

const CartContext = createContext({ count: 0, add: () => {} });

function Badge() {
  const { count } = useContext(CartContext);
  return <Text nativeID="badge" style={styles.badge}>Сагс: {count}</Text>;
}
function AddButton() {
  const { add } = useContext(CartContext);
  return <Pressable nativeID="add" style={styles.b} onPress={add}><Text style={styles.t}>Сагслах</Text></Pressable>;
}

function App() {
  const [count, setCount] = useState(0);
  const add = () => setCount((c) => c + 1);
  return (
    <CartContext.Provider value={{ count, add }}>
      <View style={styles.s}>
        <Badge />
        <AddButton />
      </View>
    </CartContext.Provider>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, gap: 16, alignItems: "center", justifyContent: "center" },
  badge: { fontSize: 22, fontWeight: "bold" },
  b: { backgroundColor: "#2563eb", padding: 14, borderRadius: 12 }, t: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);
